bounded_host_request.command:
set -euo pipefail
root="$(git rev-parse --show-toplevel)"
main="$root/deploy/gserver-compose.yaml"
clean="$root/.worktrees/profile-live-20261114/deploy/gserver-compose.yaml"
{
echo PR47_DEPLOY_DIAG
echo MAIN_COMPOSE_VALID=$(docker compose -p deploy -f "$main" config -q >/dev/null 2>&1 && echo yes || echo no)
echo CLEAN_COMPOSE_VALID=$(docker compose -p deploy -f "$clean" config -q >/dev/null 2>&1 && echo yes || echo no)
echo MAIN_HAS_PROFILE_STORAGE=$(grep -c 'PROFILE_PR_STORAGE_DIR' "$main" || true)
echo MAIN_HAS_ROOM_WORKER=$(grep -c 'GAYBBS_ROOM_EVENT_WORKER_ENABLED' "$main" || true)
echo IMAGE_LIVE=$(docker inspect --format '{{.Image}}' deploy-gaybbs-1)
echo IMAGE_TAG=$(docker image inspect --format '{{.Id}}' gace-tgtumbler-gaybbs:local)
echo IMAGE_CANDIDATE=$(docker image inspect --format '{{.Id}}' gace-tgtumbler-gaybbs:pr47-candidate)
echo POSTGRES_RUNNING=$(docker inspect --format '{{.State.Running}}' deploy-postgres-1 2>/dev/null || echo unknown)
} | gh issue comment 4 --repo seigo-gace/GateApp-Bot --body-file - >/dev/null
